input.command:
cd rulesets
cat > production-pr-review.json <<'E'
{
  "name": "production-require-pr-review",
  "target": "branch",
  "enforcement": "active",
  "conditions": {
    "ref_name": { "include": ["~DEFAULT_BRANCH"], "exclude": [] },
    "repository_property": {
      "include": [ { "name": "tier", "source": "custom", "property_values": ["production"] } ],
      "exclude": []
    }
  },
  "rules": [
    { "type": "pull_request",
      "parameters": {
        "required_approving_review_count": 1,
        "dismiss_stale_reviews_on_push": true,
        "require_code_owner_review": false,
        "require_last_push_approval": false,
        "required_review_thread_resolution": false
      } }
  ]
}
E
sed -e 's/production-require-pr-review/production-topic-require-pr-review/' -e '/"repository_property"/,/^    }$/c\    "repository_name": { "include": ["billing-api", "ledger"], "exclude": [] }' production-pr-review.json > production-topic-pr-review.json
python3 -c "import json;[json.load(open(f)) for f in ['production-pr-review.json','production-topic-pr-review.json']]" && cat production-topic-pr-review.json
for f in production-pr-review.json production-topic-pr-review.json; do gh api -X POST orgs/northwind/rulesets --input $f --jq '[.id,.name,.enforcement]|@tsv'; done

